+package com.example;
+
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Application-scoped, in-memory storage. It intentionally outlives individual
+ * views, while still requiring no persistence configuration.
+ */
+@Service
+public class ContactMessageStore {
+
+    private final CopyOnWriteArrayList<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public List<ContactMessage> findAll() {
+        return List.copyOf(messages);
+    }
+}
