+package com.example;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.component.Key;
+
+/** The form and the messages submitted to it during this application run. */
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>(ContactMessage.class, false);
+    private final ContactMessageStore store;
+
+    /* Suppresses the edit listener while a successful submission clears fields. */
+    private boolean clearingForm;
+
+    public ContactView(ContactMessageStore store) {
+        this.store = store;
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        configureGrid();
+        configureForm();
+        add(name, email, phone, message, send, messages);
+        refreshMessages();
+    }
+
+    private void configureGrid() {
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        messages.setWidthFull();
+    }
+
+    private void configureForm() {
+        // The untouched form is deliberately sendable. Only a successful send
+        // leaves the button disabled, until a person edits a field again.
+        send.addClickListener(event -> send());
+        send.addClickShortcut(Key.ENTER);
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(event -> enableAfterEdit());
+        email.addValueChangeListener(event -> enableAfterEdit());
+        phone.addValueChangeListener(event -> enableAfterEdit());
+        message.addValueChangeListener(event -> enableAfterEdit());
+    }
+
+    private void enableAfterEdit() {
+        if (!clearingForm) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void send() {
+        clearValidation();
+        boolean valid = validateForm();
+        if (!valid) {
+            return;
+        }
+
+        store.add(new ContactMessage(name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        refreshMessages();
+        clearingForm = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearingForm = false;
+        }
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private void clearValidation() {
+        setValid(name);
+        setValid(email);
+        setValid(phone);
+        setValid(message);
+    }
+
+    private void setValid(com.vaadin.flow.component.HasValidation field) {
+        field.setInvalid(false);
+        field.setErrorMessage(null);
+    }
+
+    private boolean validateForm() {
+        boolean valid = true;
+        if (blank(name.getValue())) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+        if (!blank(email.getValue()) && !isEmailAddress(email.getValue())) {
+            invalidate(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (blank(email.getValue()) && blank(phone.getValue())) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (blank(message.getValue())) {
+            invalidate(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private void invalidate(com.vaadin.flow.component.HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private boolean blank(String value) {
+        return value == null || value.isBlank();
+    }
+
+    /* A deliberately small, server-side address check for the form's contract. */
+    private boolean isEmailAddress(String value) {
+        return value.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    }
+
+    private void refreshMessages() {
+        messages.setItems(store.findAll());
+    }
+
+    private boolean hasUnsavedChanges() {
+        return !blank(name.getValue()) || !blank(email.getValue()) || !blank(phone.getValue()) || !blank(message.getValue());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedChanges()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(keepEditing, discard);
+        dialog.open();
+    }
+}
